# Runs list_invoices for real: customer 42 is logged in and asks for customer_id=17, on synthetic invoices.
import asyncio
import inspect
import json
import sqlite3
from decimal import Decimal
from http import HTTPStatus


class HTTPException(Exception):
    def __init__(self, status_code, detail=None):
        super().__init__(status_code, detail)
        self.status_code, self.detail = status_code, detail


class Router:
    def get(self, path, **kwargs):
        return lambda fn: fn


def Depends(dependency=None):
    return dependency


class User:
    def __init__(self, customer_id):
        self.customer_id = customer_id


def current_user():
    return User(42)


INVOICES = [  # id, customer, amount, status
    (1695, 42, "512.00", "paid"),
    (1716, 42, "89.90", "due"),
    (1703, 17, "1240.00", "paid"),
    (1711, 17, "385.50", "due"),
    (1729, 17, "2016.00", "due"),
]
OWNER = {i: c for i, c, _, _ in INVOICES}


class DB:
    def __init__(self):
        self.conn = sqlite3.connect(":memory:")
        self.conn.row_factory = sqlite3.Row
        self.conn.execute("CREATE TABLE invoices (id INTEGER PRIMARY KEY, customer_id INTEGER, amount TEXT, status TEXT)")
        self.conn.executemany("INSERT INTO invoices VALUES (?, ?, ?, ?)", INVOICES)

    def execute(self, sql, params=None):
        return self.conn.execute(sql, params or {})


def status(code):
    try:
        return f"{code} {HTTPStatus(code).phrase}"
    except ValueError:
        return str(code)


def owner(r):
    try:
        return OWNER.get(r["id"])
    except Exception:
        return None


def row(r):
    try:
        return [f"INV-{r['id']}", f"AUD {Decimal(str(r['amount'])):,.2f}", r["status"]]
    except Exception:
        return [str(r)]


ns = {"__name__": "subject", "router": Router(), "Depends": Depends, "User": User, "current_user": current_user,
      "db": DB(), "HTTPException": HTTPException}
with open("subject.py", encoding="utf-8") as f:
    exec(compile(f.read(), "subject.py", "exec"), ns)

try:
    got = ns["list_invoices"](customer_id=17, user=User(42))
    if inspect.iscoroutine(got):  # an async endpoint: the framework awaits it
        got = asyncio.run(got)
except HTTPException as e:
    out = {"option": str(e.status_code), "status": status(e.status_code), "result": "No invoices", "rows": [],
           "detail": f"list_invoices raised HTTPException({e.status_code}) for customer 42 asking for customer 17."}
except Exception as e:
    out = {"option": "500", "status": status(500), "result": "No invoices", "rows": [],
           "detail": f"list_invoices raised {type(e).__name__}: {e}"}
else:
    try:
        rows = [] if got is None else list(got)
    except Exception:  # not a list of rows
        rows = None
    owners = {owner(r) for r in rows or []}
    if got is None:
        option, result = "null", "null"
    elif rows is None:
        option, result = "unknown", repr(got)[:200]
    elif not rows:
        option, result = "empty", "An empty list"
    elif 17 in owners:
        option, result = "others", "Customer 17's invoices"
    elif owners == {42}:
        option, result = "own", "Customer 42's own invoices"
    else:
        option, result = "unknown", f"{len(rows)} rows of unknown owner"
    out = {"option": option, "status": status(200), "result": result, "rows": [row(r) for r in rows or []],
           "detail": f"Logged in as customer 42, list_invoices(customer_id=17) returned {result[0].lower() + result[1:]}."}
print(json.dumps(out))

