# Runs invoice_pdf for real: customer 42 is logged in and asks for invoice 1703, which belongs to customer 17.
import asyncio
import inspect
import json
from decimal import Decimal
from http import HTTPStatus


class HTTPException(Exception):
    def __init__(self, status_code, detail=None):
        super().__init__(status_code, detail)
        self.status_code, self.detail = status_code, detail


class Router:
    def get(self, path, **kwargs):
        return lambda fn: fn


def Depends(dependency=None):
    return dependency


class User:
    def __init__(self, customer_id):
        self.customer_id = customer_id


def current_user():
    return User(42)


class Invoice:
    def __init__(self, id, customer_id, total, status):
        self.id, self.customer_id, self.total, self.status = id, customer_id, Decimal(total), status


class DB:
    def __init__(self, rows):
        self.rows = {r.id: r for r in rows}

    def get(self, model, key):
        return self.rows.get(key) if model is Invoice else None


class PDF(bytes):
    pass


def render_pdf(inv):
    return PDF(f"%PDF-1.7 invoice {inv.id}, total AUD {inv.total:,.2f}".encode())


def status(code):
    try:
        return f"{code} {HTTPStatus(code).phrase}"
    except ValueError:
        return str(code)


db = DB([Invoice(1695, 42, "512.00", "paid"), Invoice(1716, 42, "89.90", "due"),
         Invoice(1703, 17, "1240.00", "paid"), Invoice(1711, 17, "385.50", "due")])
ns = {"__name__": "subject", "router": Router(), "Depends": Depends, "User": User, "current_user": current_user,
      "db": db, "Invoice": Invoice, "HTTPException": HTTPException, "render_pdf": render_pdf}
with open("subject.py", encoding="utf-8") as f:
    exec(compile(f.read(), "subject.py", "exec"), ns)

try:
    got = ns["invoice_pdf"](invoice_id=1703, user=User(42))
    if inspect.iscoroutine(got):  # an async endpoint: the framework awaits it
        got = asyncio.run(got)
except HTTPException as e:
    out = {"option": str(e.status_code), "status": status(e.status_code), "result": "No PDF. The invoice belongs to customer 17.",
           "rows": [], "detail": f"invoice_pdf raised HTTPException({e.status_code}) for customer 42 asking for invoice 1703."}
except Exception as e:
    out = {"option": "500", "status": status(500), "result": "No PDF. The server failed.", "rows": [],
           "detail": f"invoice_pdf raised {type(e).__name__}: {e}"}
else:
    pdf = isinstance(got, PDF) and b"invoice 1703," in got
    out = {"option": "pdf" if pdf else "200", "status": status(200),
           "result": "The PDF of invoice 1703" if pdf else repr(got)[:200], "rows": [],
           "detail": "Logged in as customer 42, invoice_pdf(1703) returned " + ("customer 17's PDF." if pdf else "something other than the PDF.")}
print(json.dumps(out))
